using System;
using System.Collections.Generic;
using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "LacertianBeamAction", menuName = "Data/Battle/Battle Actions/Hevelius/LacertianBeam Action")]
public class LacertianBeamAction : BattleAction
{
	[Serializable]
	public class EnemyPositionBeamScale
	{
		[SerializeField]
		private TransformReference enemyPositionTransformReference;

		public float xScaleBeam;

		public float zRotationBeam;

		public Vector2 enemyPosition => enemyPositionTransformReference.value.position;
	}

	[Header("Link Beam")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private int additionalTimesAmount = 6;

	[Header("Purify Action")]
	[SerializeField]
	private PurifiedLightningAction purifiedLightningAction;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	[SerializeField]
	private EnemyPositionBeamScale[] enemyPositionBeamScales;

	public int AdditionalTimesAmount => additionalTimesAmount;

	public PurifyAction PurifyAction => purifyAction;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return GetLinkAmount() > 0;
	}

	public int GetLinkAmount()
	{
		int num = 0;
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			CompanionEffects component = currentCompanions.ActiveCompanions[i].GetComponent<CompanionEffects>();
			num += component.IsLinksActiveGetAmount();
		}
		if (num == 8)
		{
			num += additionalTimesAmount;
		}
		return num;
	}

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		if (IsVFXEnabled())
		{
			PlaySFXWithParameter("release", 0);
			ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
			GameObject vfx = GetVFX();
			Transform child = vfx.transform.GetChild(0).GetChild(0);
			EnemyPositionBeamScale enemyPositionBeamScale = GetEnemyPositionBeamScale(target);
			child.SetLocalScaleX(enemyPositionBeamScale.xScaleBeam);
			child.SetLocalEulerAnglesZ(enemyPositionBeamScale.zRotationBeam);
			ParticleEmissionController particleEmissionController = vfx.GetComponent<ParticleEmissionController>();
			particleEmissionController.SetActive(value: true);
			List<Transform> children = vfx.transform.GetChild(0).GetChildren();
			GameObject gameObject = children[children.Count - 2].gameObject;
			GameObject gameObject2 = children.Last().gameObject;
			gameObject.SetActive(value: false);
			gameObject2.SetActive(value: false);
			GameObject gameObject3 = currentCompanions.ActiveCompanions[0];
			if (currentCompanions.ActiveCompanions.Count == 2)
			{
				if (gameObject3.GetComponent<CompanionEffects>().IsLinksActiveGetAmount() > 0)
				{
					gameObject.SetActive(value: true);
				}
				if (currentCompanions.ActiveCompanions[1].GetComponent<CompanionEffects>().IsLinksActiveGetAmount() > 0)
				{
					gameObject2.SetActive(value: true);
				}
			}
			else if (gameObject3.GetComponent<CompanionEffects>().IsLinksActiveGetAmount() > 0)
			{
				if (gameObject3.GetComponent<CompanionInitializer>().PositioningIndex == 0)
				{
					gameObject.SetActive(value: true);
				}
				else
				{
					gameObject2.SetActive(value: true);
				}
			}
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, vfxDelay, delegate
			{
				GameObject secondVFX = GetSecondVFX(GetVFXOwnerPosition(target));
				ParticleEmissionController secondParticleEmissionController = secondVFX.GetComponent<ParticleEmissionController>();
				secondParticleEmissionController.SetActive(value: true);
				purifiedLightningAction.SingleTargetCastDefault(target, GetLinkAmount(), purifyAmount, source, null, null, delegate
				{
					particleEmissionController.SetActive(value: false);
					secondParticleEmissionController.SetActive(value: false);
					ReferenceSingleton<PoolHandler>.Instance.StoreObject(vfx, 0.5f);
					ReferenceSingleton<PoolHandler>.Instance.StoreObject(secondVFX, 0.5f);
					SetSFXWithParameter("release", 1, release: true);
				});
			});
		}
		else
		{
			purifiedLightningAction.SingleTargetCastDefault(target, GetLinkAmount(), purifyAmount, source);
		}
	}

	public EnemyPositionBeamScale GetEnemyPositionBeamScale(GameObject target)
	{
		for (int i = 0; i < enemyPositionBeamScales.Length; i++)
		{
			if ((Vector2)target.transform.position == enemyPositionBeamScales[i].enemyPosition)
			{
				return enemyPositionBeamScales[i];
			}
		}
		return null;
	}
}
